Lock lock = new XxxLock();
// ...
lock.lock();
try {
doSomething();
doOthers();
} finally {
lock.unlock();
}

Lock lock = new XxxLock();
// ...
try {
// 如果此处抛出异常，则直接执行finally代码块
doSomething();
// 无论加锁是否成功，finally代码块都会执行
lock.lock();
doOthers();
} finally {
lock.unlock();
}

Lock lock = new XxxLock();
// ...
boolean isLocked = lock.tryLock();
if (isLocked) {
try {
doSomething();
doOthers();
} finally {
lock.unlock();
}
}

public class LazyInitDemo {
private volatile Helper helper = null;
public Helper getHelper() {
if (helper == null) {
synchronized(this) {
if (helper == null) {
helper = new Helper();
}
}
}
return helper;
}
// other methods and fields...
}

